"""Shared English/neutral Spanish for personal demonstrated delivery routes."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]/'src/main/resources/assets/bunnidogs/lang'
rows={'care.bunnidogs.delivery.parcel':('Shipment: %s','Envío: %s'),'care.bunnidogs.delivery.watch':('Watch a delivery','Observar una entrega'),'care.bunnidogs.delivery.stop':('Stop watching','Dejar de observar'),'care.bunnidogs.delivery.show':('Show route','Mostrar recorrido'),'care.bunnidogs.delivery.pause':('Pause delivery','Pausar entrega'),'care.bunnidogs.delivery.resume':('Resume delivery','Reanudar entrega'),'care.bunnidogs.delivery.clear':('Forget route','Olvidar recorrido'),'care.bunnidogs.delivery.unload':('Unload parcel','Recuperar carga'),'care.bunnidogs.delivery.watching':('Watching your delivery','Observando tu entrega'),'message.bunnidogs.delivery.watching':('%s is watching your delivery.','%s está observando tu entrega.'),'message.bunnidogs.delivery.pickup_seen':('%s noticed the pickup.','%s observó la recogida.'),'message.bunnidogs.delivery.learned':('%s remembers this delivery.','%s recuerda esta entrega.')}
states={'none':('No delivery route','Sin recorrido de entrega'),'watching':('Watching your delivery','Observando tu entrega'),'empty_source':('Waiting for supplies','Esperando suministros'),'full_target':('The destination is full','El destino está lleno'),'changed_store':('A remembered container changed','Un contenedor conocido cambió'),'paused_store':('A work site is paused or locked','Un lugar de trabajo está pausado o cerrado'),'guidance':('Needs its guide nearby','Necesita a su guía cerca'),'paused':('Delivery paused','Entrega pausada'),'unavailable':('Waiting to work','Esperando para trabajar'),'unloaded':('The route is outside the loaded area','El recorrido está fuera de la zona cargada'),'resting':('Resting between deliveries','Descansando entre entregas'),'walking':('Collecting the shipment','Recogiendo el envío'),'carrying':('Carrying a parcel','Transportando una carga'),'ready':('Remembers a delivery route','Recuerda un recorrido de entrega'),'blocked':('The route is blocked','El recorrido está bloqueado')}
for key,pair in states.items():
 rows['care.bunnidogs.delivery.state.'+key]=pair
 rows['message.bunnidogs.delivery.state.'+key]=('%s: '+pair[0],'%s: '+pair[1])
for key,pair in {'young':('Wait until adulthood.','Espera hasta que sea adulto.'),'parcel':('Finish or unload the current parcel.','Termina la entrega o recupera la carga actual.'),'senses':('Needs a sharper sense of direction.','Necesita orientarse mejor.'),'complex':('This delivery is too complex.','Esta entrega es demasiado compleja.'),'ready':('Wait until rested, nearby and safe.','Espera a que esté cerca, descansado y a salvo.')}.items():rows['care.bunnidogs.delivery.reason.'+key]=pair
for index,locale in enumerate(['en_us','es_pe']):
 p=root/(locale+'.json');data=json.loads(p.read_text());data.update({key:pair[index] for key,pair in rows.items()});p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
